import{_ as o,o as a,c as i,a2 as r}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"14.6 理论机考题型与答题技巧","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-6-li-lun-ji-kao-ti-xing-yu-da-ti-ji-qiao.md","filePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-6-li-lun-ji-kao-ti-xing-yu-da-ti-ji-qiao.md","lastUpdated":1793096070000}'),l={name:"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-6-li-lun-ji-kao-ti-xing-yu-da-ti-ji-qiao.md"};function e(n,t,d,s,u,h){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_14-6-理论机考题型与答题技巧" tabindex="-1">14.6 理论机考题型与答题技巧 <a class="header-anchor" href="#_14-6-理论机考题型与答题技巧" aria-label="Permalink to &quot;14.6 理论机考题型与答题技巧&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>理论是<strong>电脑答题</strong>,题量不小、及格线不低。这一节摸清题型结构,掌握&quot;判断+单选&quot;的答题技巧和复习重点,助你稳稳过线。</p><h2 id="一、理论机考的一般情况" tabindex="-1">一、理论机考的一般情况 <a class="header-anchor" href="#一、理论机考的一般情况" aria-label="Permalink to &quot;一、理论机考的一般情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>考试形式</td><td>电脑机考,当场出分</td></tr><tr><td>题型</td><td>判断题 + 单选题(部分地方有少量多选题)</td></tr><tr><td>题量</td><td>一般 100 题左右</td></tr><tr><td>满分/及格</td><td>满分 100 分,<strong>80 分及格</strong>(各地以考务通知为准)</td></tr><tr><td>考试范围</td><td>法律法规、基础知识、安全技术、急救实操理论等</td></tr></tbody></table><blockquote><p>⚠️ 以当地<strong>报名机构的考务说明</strong>为准;机考答题要注意时间分配,别在一道题上纠结太久。</p></blockquote><h2 id="二、判断题答题技巧" tabindex="-1">二、判断题答题技巧 <a class="header-anchor" href="#二、判断题答题技巧" aria-label="Permalink to &quot;二、判断题答题技巧&quot;">​</a></h2><ol><li><strong>看绝对词</strong>:出现&quot;<strong>一定、必须、肯定、任何、全部、绝对、禁止</strong>&quot;等绝对化表述时,多长个心眼——很多是错的(但也要结合知识点判断,如&quot;开关必须接火线&quot;这类本身就是绝对正确);</li><li><strong>抓安全常识</strong>:涉及&quot;带电作业、徒手拉触电者、接零接地混用&quot;等安全底线,考的是&quot;对不对&quot;,安全红线都是&quot;错&quot;的方向;</li><li><strong>抓关键词</strong>:&quot;短路产生大电流、验电先验证、接地线先接地端&quot;等<strong>规范动作</strong>,一般是&quot;对&quot;。</li></ol><h2 id="三、单选题答题技巧" tabindex="-1">三、单选题答题技巧 <a class="header-anchor" href="#三、单选题答题技巧" aria-label="Permalink to &quot;三、单选题答题技巧&quot;">​</a></h2><ul><li><strong>排除法</strong>:先排除明显错误项(与安全常识相悖、数值离谱的);</li><li><strong>数值题靠记忆</strong>:安全电压等级、电流阈值(1/10/50mA)、接地电阻(4Ω/10Ω)、同步转速公式等,背熟;</li><li><strong>看&quot;最/首先/应&quot;</strong>:题干问&quot;首先应&quot;&quot;最主要&quot;&quot;应选用&quot;时,选规范流程的第一步或最标准的做法;</li><li><strong>遇到不会的</strong>:结合&quot;安全第一&quot;原则选,不要空着不选。</li></ul><h2 id="四、高频考点清单-背这些就够" tabindex="-1">四、高频考点清单(背这些就够) <a class="header-anchor" href="#四、高频考点清单-背这些就够" aria-label="Permalink to &quot;四、高频考点清单(背这些就够)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>常考知识点</th></tr></thead><tbody><tr><td>法规</td><td>特种作业人员条件(18 岁以上、健康)、证书 6 年有效期、3 年复审</td></tr><tr><td>电工基础</td><td>欧姆定律、串并联、交流电频率 50Hz、220V 有效值、三相 380V</td></tr><tr><td>安全技术</td><td>安全电压 42/36/24/12/6、安全电流 1/10/50mA、接地电阻、漏电保护</td></tr><tr><td>电器</td><td>断路器、接触器、热继电器、熔断器的作用和符号</td></tr><tr><td>电机</td><td>异步原理、转差率、Y/△ 接法、启动与反转</td></tr><tr><td>急救防火</td><td>先断电、干粉灭火、心肺复苏 30:2、触电先脱离电源</td></tr></tbody></table><h2 id="五、复习策略建议" tabindex="-1">五、复习策略建议 <a class="header-anchor" href="#五、复习策略建议" aria-label="Permalink to &quot;五、复习策略建议&quot;">​</a></h2><ol><li><strong>先过一遍本套文档的&quot;考点提示&quot;</strong>,把 ✅ 必背点背熟;</li><li><strong>做自测练习</strong>:每节末尾的练习题相当于&quot;仿真题&quot;,做错的知识点回到正文看;</li><li><strong>错题归因</strong>:把做错的题按&quot;数值记不住 / 概念混淆 / 粗心&quot;分类,针对性补;</li><li><strong>考前两天</strong>:重点再过一遍安全技术、急救、法规三个板块。</li></ol><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 理论机考:判断+单选,满分 100,80 分及格(以当地通知为准)。</li><li>✅ 答题技巧:排除法、抓关键词、结合&quot;安全第一&quot;。</li><li>✅ 高频必背:安全电压/电流数值、接地电阻、心肺复苏比例、证书有效期。</li><li>⚠️ 易混点:别把理论当&quot;纯背&quot;,要理解&quot;为什么&quot;——理解了的题,换着问法也不会错。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>题型:判断+单选,机考当场出分,80 分及格。</li><li>技巧:排除法、抓绝对词、结合安全常识。</li><li>复习:背熟考点清单 + 做完自测练习 + 错题归因。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)低压电工理论考试一般满分 100 分,80 分及格。( )</li><li>(单选)答题时遇到不会的单选题,下列做法较好的是()。 A. 直接跳过不选　B. 用排除法并结合&quot;安全第一&quot;原则选　C. 猜一个最长的选项　D. 随便点</li><li>(判断)特种作业操作证有效期 6 年,每 3 年复审一次。( )</li><li>(单选)下列数值中,属于我国安全电压等级的是()。 A. 110V　B. 36V　C. 220V　D. 380V</li><li>(判断)做错的题目应回到知识点重新理解,而不是只记答案。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。一般满分 100 分、80 分及格(以当地通知为准)。</li><li><strong>B</strong>。排除法 + 安全原则,不空题。</li><li><strong>√</strong>。证书 6 年有效期、3 年复审。</li><li><strong>B</strong>。安全电压等级含 36V(42/36/24/12/6V)。</li><li><strong>√</strong>。理解知识点比死记答案更有效。</li></ol></details>',21)])])}const g=o(l,[["render",e]]);export{c as __pageData,g as default};
